import{_ as i,a0 as o,w as l,s as r,ao as d,I as p,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"使用 Terminator 在一个窗口中运行多个终端 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Terminator 在一个窗口中运行多个终端 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Terminator 在一个窗口中运行多个终端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Terminator 在一个窗口中运行多个终端 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window","title":"使用 Terminator 在一个窗口中运行多个终端","tag":"201909","desc":""},"relativePath":"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window.md","filePath":"[post].md"}'),c={name:"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window.md"};function m(u,n,h,g,f,T){const s=o("Link");return l(),r("div",null,[n[15]||(n[15]=d(`<h1 id="使用-terminator-在一个窗口中运行多个终端" tabindex="-1">使用 Terminator 在一个窗口中运行多个终端 <a class="header-anchor" href="#使用-terminator-在一个窗口中运行多个终端" aria-label="Permalink to “使用 Terminator 在一个窗口中运行多个终端”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201909/30/233732j9jjx3xxuujopiuu.jpg" alt=""></p><blockquote><p>Terminator 为在单窗口中运行多个 GNOME 终端提供了一个选择，让你可以灵活地调整工作空间来适应你的需求。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/09/terminator-code-100810364-large.jpg" alt=""></p><p>如果你曾经希望可以排列多个终端并将它们组织在一个窗口中，那么我们可能会给你带来一个好消息。 Linux 的 Terminator 可以为你做到这一点。没有问题！</p><h3 id="分割窗口" tabindex="-1">分割窗口 <a class="header-anchor" href="#分割窗口" aria-label="Permalink to “分割窗口”">​</a></h3><p>Terminator 最初打开像是一个单一窗口的终端窗口一样。但是，一旦在该窗口中单击鼠标，它将弹出一个选项，让你可以灵活地进行更改。你可以选择“水平分割”或“垂直分割”，将你当前所在的窗口分为两个较小的窗口。实际上，菜单旁会有小的分割结果图示（类似于 <code>=</code> and <code>||</code>），你可以根据需要重复拆分窗口。当然，你如果将整个窗口分为六个或九个以上，那么你可能会发现它们太小而无法有效使用。</p><p>使用 ASCII 艺术来说明分割窗口的过程，你可能会看到类似以下的样子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+-------------------+     +-------------------+     +-------------------+</span></span>
<span class="line"><span>|                   |     |                   |     |                   |</span></span>
<span class="line"><span>|                   |     |                   |     |                   |</span></span>
<span class="line"><span>|                   | ==&gt; |-------------------| ==&gt; |-------------------|</span></span>
<span class="line"><span>|                   |     |                   |     |         |         |</span></span>
<span class="line"><span>|                   |     |                   |     |         |         |</span></span>
<span class="line"><span>+-------------------+     +-------------------+     +-------------------+</span></span>
<span class="line"><span>  原始终端                       水平分割                   垂直分割</span></span></code></pre></div><p>另一种拆分窗口的方法是使用控制键组合，例如，使用 <code>Ctrl+Shift+e</code> 垂直分割窗口，使用 <code>Ctrl+Shift+o</code>（“o” 表示“打开”）水平分割窗口。</p><p>在 Terminator 分割完成后，你可以点击任意窗口使用，并根据工作需求在窗口间移动。</p><h3 id="最大化窗口" tabindex="-1">最大化窗口 <a class="header-anchor" href="#最大化窗口" aria-label="Permalink to “最大化窗口”">​</a></h3><p>如果你想暂时忽略除了一个窗口外的其他窗口而只关注一个，你可以单击该窗口，然后从菜单中选择“最大化”选项。接着该窗口会撑满所有空间。再次单击并选择“还原所有终端”可以返回到多窗口显示。使用 <code>Ctrl+Shift+x</code> 将在正常和最大化设置之间切换。</p><p>窗口标签上的窗口大小指示（例如 80x15）显示了每行的字符数以及每个窗口的行数。</p><h3 id="关闭窗口" tabindex="-1">关闭窗口 <a class="header-anchor" href="#关闭窗口" aria-label="Permalink to “关闭窗口”">​</a></h3><p>要关闭任何窗口，请打开 Terminator 菜单，然后选择“关闭”。其他窗口将自行调整占用空间，直到你关闭最后一个窗口。</p><h3 id="保存你的自定义设置" tabindex="-1">保存你的自定义设置 <a class="header-anchor" href="#保存你的自定义设置" aria-label="Permalink to “保存你的自定义设置”">​</a></h3><p>将窗口分为多个部分后，将自定义的 Terminator 设置设置为默认非常容易。从弹出菜单中选择“首选项”，然后从打开的窗口顶部的选项卡中选择“布局”。接着你应该看到列出了“新布局”。只需单击底部的“保存”，然后单击右下角的“关闭”。Terminator 会将你的设置保存在 <code>~/.config/terminator/config</code> 中，然后每次使用到时都会使用该文件。</p><p>你也可以通过使用鼠标拉伸来扩大整个窗口。再说一次，如果要保留更改，请从菜单中选择“首选项”，“布局”，接着选择“保存”和“关闭”。</p><h3 id="在保存的配置之间进行选择" tabindex="-1">在保存的配置之间进行选择 <a class="header-anchor" href="#在保存的配置之间进行选择" aria-label="Permalink to “在保存的配置之间进行选择”">​</a></h3><p>如果愿意，你可以通过维护多个配置文件来设置多种 Terminator 窗口布局，重命名每个配置文件（如 <code>config-1</code>、<code>config-2</code>），接着在你想使用它时将它移动到 <code>~/.config/terminator/config</code>。这有一个类似执行此任务的脚本。它让你在 3 个预配置的窗口布局之间进行选择。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PS3=&#39;Terminator options: &#39;</span></span>
<span class="line"><span>options=(&quot;Split 1&quot; &quot;Split 2&quot; &quot;Split 3&quot; &quot;Quit&quot;)</span></span>
<span class="line"><span>select opt in &quot;\${options[@]}&quot;</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    case $opt in</span></span>
<span class="line"><span>        &quot;Split 1&quot;)</span></span>
<span class="line"><span>            config=config-1</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        &quot;Split 2&quot;)</span></span>
<span class="line"><span>            config=config-2</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        &quot;Split 3&quot;)</span></span>
<span class="line"><span>            config=config-3</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        *)</span></span>
<span class="line"><span>            exit</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>    esac</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd ~/.config/terminator</span></span>
<span class="line"><span>cp config config-</span></span>
<span class="line"><span>cp $config config</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>terminator &amp;</span></span></code></pre></div><p>如果有用的话，你可以给选项一个比 <code>config-1</code> 更有意义的名称。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Terminator 是设置多窗口处理相关任务的不错选择。如果你从未使用过它，那么可能需要先使用 <code>sudo apt install terminator</code> 或 <code>sudo yum install -y terminator</code> 之类的命令进行安装。</p><p>希望你喜欢使用 Terminator。还有，如另一个同名角色所说，“我会回来的！”</p><hr>`,27)),p("p",null,[n[1]||(n[1]=a("via: ",-1)),e(s,{href:"https://www.networkworld.com/article/3436784/how-to-use-terminator-on-linux-to-run-multiple-terminals-in-one-window.html"},{default:t(()=>[...n[0]||(n[0]=[a("https://www.networkworld.com/article/3436784/how-to-use-terminator-on-linux-to-run-multiple-terminals-in-one-window.html",-1)])]),_:1})]),p("p",null,[n[6]||(n[6]=a("作者：",-1)),e(s,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...n[2]||(n[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),n[7]||(n[7]=a(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...n[3]||(n[3]=[a("lujun9972",-1)])]),_:1}),n[8]||(n[8]=a(" 译者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:t(()=>[...n[4]||(n[4]=[a("geekpi",-1)])]),_:1}),n[9]||(n[9]=a(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:t(()=>[...n[5]||(n[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[n[12]||(n[12]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...n[10]||(n[10]=[a("LCTT",-1)])]),_:1}),n[13]||(n[13]=a(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:t(()=>[...n[11]||(n[11]=[a("Linux中国",-1)])]),_:1}),n[14]||(n[14]=a(" 荣誉推出",-1))])])}const x=i(c,[["render",m]]);export{w as __pageData,x as default};
